<?php
/**
 * REST controller — validates HMAC-signed one-time SSO tokens and logs the
 * mapped user in.
 *
 * Token format (generated by the Digivault backend):
 *   payload = base64url( json{ email, name, role, exp, jti } )
 *   sig     = hex( HMAC-SHA256( payload, shared_secret ) )
 *   URL     = /wp-json/digivault/v1/sso?p=<payload>&s=<sig>
 *
 * Guarantees:
 *   - signature verified with hash_equals (constant time)
 *   - exp must be in the future (Digivault issues 120-second tokens)
 *   - jti is single-use (burned via a transient for 15 minutes)
 *   - role is restricted to administrator|editor
 *
 * @package Digivault_Connect
 */

defined( 'ABSPATH' ) || exit;

/**
 * Registers and handles GET /digivault/v1/sso.
 */
class Digivault_Connect_Rest_Controller {

	const ALLOWED_ROLES = array( 'administrator', 'editor' );

	/**
	 * Hook route registration.
	 */
	public function __construct() {
		add_action( 'rest_api_init', array( $this, 'register_routes' ) );
	}

	/**
	 * Register the SSO route.
	 *
	 * @return void
	 */
	public function register_routes() {
		register_rest_route(
			'digivault/v1',
			'/sso',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'callback'            => array( $this, 'handle_sso' ),
				// The token itself is the credential — validated in the callback.
				'permission_callback' => '__return_true',
				'args'                => array(
					'p' => array(
						'required'          => true,
						'type'              => 'string',
						'sanitize_callback' => 'sanitize_text_field',
					),
					's' => array(
						'required'          => true,
						'type'              => 'string',
						'sanitize_callback' => 'sanitize_text_field',
					),
				),
			)
		);
	}

	/**
	 * Validate the token and log the user in.
	 *
	 * @param WP_REST_Request $request Incoming request.
	 * @return WP_REST_Response|WP_Error
	 */
	public function handle_sso( WP_REST_Request $request ) {
		$secret = Digivault_Connect_Settings::get_secret();
		if ( '' === $secret ) {
			return new WP_Error(
				'dvc_not_configured',
				__( 'Digivault Connect has no shared secret configured.', 'digivault-connect' ),
				array( 'status' => 503 )
			);
		}

		$payload_b64 = (string) $request->get_param( 'p' );
		$signature   = (string) $request->get_param( 's' );

		$expected = hash_hmac( 'sha256', $payload_b64, $secret );
		if ( ! hash_equals( $expected, strtolower( $signature ) ) ) {
			return $this->reject();
		}

		$payload = json_decode( $this->base64url_decode( $payload_b64 ), true );
		if ( ! is_array( $payload ) ) {
			return $this->reject();
		}

		$email = sanitize_email( isset( $payload['email'] ) ? $payload['email'] : '' );
		$name  = sanitize_text_field( isset( $payload['name'] ) ? $payload['name'] : '' );
		$role  = sanitize_key( isset( $payload['role'] ) ? $payload['role'] : '' );
		$exp   = isset( $payload['exp'] ) ? (int) $payload['exp'] : 0;
		$jti   = sanitize_key( isset( $payload['jti'] ) ? $payload['jti'] : '' );

		if ( ! $email || ! $jti || ! in_array( $role, self::ALLOWED_ROLES, true ) ) {
			return $this->reject();
		}
		if ( $exp < time() ) {
			return new WP_Error(
				'dvc_expired',
				__( 'This login link has expired. Generate a fresh one from Digivault.', 'digivault-connect' ),
				array( 'status' => 403 )
			);
		}

		// Single use: burn the jti before logging in.
		$jti_key = 'dvc_jti_' . $jti;
		if ( false !== get_transient( $jti_key ) ) {
			return $this->reject();
		}
		set_transient( $jti_key, 1, 15 * MINUTE_IN_SECONDS );

		$user = $this->find_or_create_user( $email, $name, $role );
		if ( is_wp_error( $user ) ) {
			return $user;
		}

		wp_set_current_user( $user->ID );
		wp_set_auth_cookie( $user->ID, false );
		do_action( 'wp_login', $user->user_login, $user );

		wp_safe_redirect( admin_url() );
		exit;
	}

	/**
	 * Find the WP user for this email, creating one with the mapped role if
	 * needed. Existing users keep their current (possibly higher) role unless
	 * they have none.
	 *
	 * @param string $email Digivault user email.
	 * @param string $name  Display name.
	 * @param string $role  administrator|editor.
	 * @return WP_User|WP_Error
	 */
	private function find_or_create_user( $email, $name, $role ) {
		$user = get_user_by( 'email', $email );
		if ( $user instanceof WP_User ) {
			if ( empty( $user->roles ) ) {
				$user->set_role( $role );
			}
			return $user;
		}

		$login   = sanitize_user( strstr( $email, '@', true ) . '_dv', true );
		$user_id = wp_insert_user(
			array(
				'user_login'   => $login,
				'user_email'   => $email,
				'user_pass'    => wp_generate_password( 32, true, true ),
				'display_name' => $name ? $name : $login,
				'role'         => $role,
			)
		);
		if ( is_wp_error( $user_id ) ) {
			return new WP_Error(
				'dvc_user_create_failed',
				__( 'Could not provision a WordPress user for this login.', 'digivault-connect' ),
				array( 'status' => 500 )
			);
		}
		return get_user_by( 'id', $user_id );
	}

	/**
	 * Uniform rejection — no detail leaks about which check failed.
	 *
	 * @return WP_Error
	 */
	private function reject() {
		return new WP_Error(
			'dvc_invalid_token',
			__( 'Invalid login token.', 'digivault-connect' ),
			array( 'status' => 403 )
		);
	}

	/**
	 * Decode URL-safe base64.
	 *
	 * @param string $data Encoded payload.
	 * @return string
	 */
	private function base64url_decode( $data ) {
		$b64 = strtr( $data, '-_', '+/' );
		$pad = strlen( $b64 ) % 4;
		if ( $pad ) {
			$b64 .= str_repeat( '=', 4 - $pad );
		}
		return (string) base64_decode( $b64, true );
	}
}
